$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root
function Write-B64([string]$Path,[string]$Data){ $full=Join-Path $Root $Path; $dir=Split-Path -Parent $full; New-Item -ItemType Directory -Force -Path $dir|Out-Null; [IO.File]::WriteAllBytes($full,[Convert]::FromBase64String($Data)) }
Write-B64 'src/core/runtime/guidedFeatureRuntime.ts' ''
Write-B64 'src/core/runtime/guidedFeatureRuntime-N-MEGA11.test.ts' ''
Write-B64 'src/features/play-mode/GuidedFeatureControlPanel.tsx' ''
$Play = Join-Path $Root 'src/features/play-mode/PlayMode.tsx'
if (!(Test-Path $Play)) { throw 'PlayMode.tsx bulunamadi.' }
$text=[IO.File]::ReadAllText($Play)
$import='import { GuidedFeatureControlPanel } from "./GuidedFeatureControlPanel";'
if (!$text.Contains($import)) {
  $anchor='import { useMemo, useState } from "react";'
  if (!$text.Contains($anchor)) { throw 'PlayMode import bolgesi bulunamadi.' }
  $text=$text.Replace($anchor,$anchor+"`r`n"+$import)
}
$panel='          <GuidedFeatureControlPanel characterId={activeCharacter.id} />'
if (!$text.Contains($panel)) {
  $anchor='          <section className="play-mode-card play-mode-rest-card">'
  if (!$text.Contains($anchor)) { throw 'PlayMode rest paneli bulunamadi.' }
  $text=$text.Replace($anchor,$panel+"`r`n`r`n"+$anchor)
}
[IO.File]::WriteAllText($Play,$text,[Text.UTF8Encoding]::new($false))
$stdout=Join-Path $env:TEMP 'e4-nmega11-out.log'; $stderr=Join-Path $env:TEMP 'e4-nmega11-err.log'
Remove-Item $stdout,$stderr -Force -ErrorAction SilentlyContinue
$testProc=Start-Process -FilePath 'cmd.exe' -ArgumentList @('/d','/s','/c','npm.cmd exec vitest run -- src/core/runtime/guidedFeatureRuntime-N-MEGA11.test.ts') -WorkingDirectory $Root -Wait -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr
if ($testProc.ExitCode -ne 0) { Write-Host 'N-MEGA11 RED - TEST'; Get-Content $stdout,$stderr -Tail 60; exit $testProc.ExitCode }
Remove-Item $stdout,$stderr -Force -ErrorAction SilentlyContinue
$buildProc=Start-Process -FilePath 'cmd.exe' -ArgumentList @('/d','/s','/c','npm.cmd run build') -WorkingDirectory $Root -Wait -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr
if ($buildProc.ExitCode -ne 0) { Write-Host 'N-MEGA11 RED - BUILD'; Get-Content $stdout,$stderr -Tail 60; exit $buildProc.ExitCode }
Remove-Item $stdout,$stderr -Force -ErrorAction SilentlyContinue
Write-Host 'N-MEGA11 GREEN'
